def transform(grid):
    g = [row[:] for row in grid]
    R, C = len(g), len(g[0])
    seen = set()
    for r in range(R):
        for c in range(C):
            if g[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < R and 0 <= ny < C and g[nx][ny] == 5 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        stack.append((nx,ny))
            r0 = min(x for x,y in comp)
            r1 = max(x for x,y in comp)
            c0 = min(y for x,y in comp)
            c1 = max(y for x,y in comp)
            # Fill the hollow interior and the gap in the upper border.
            for x in range(r0, r1+1):
                for y in range(c0, c1+1):
                    if g[x][y] == 0 and x > r0 and x < r1 and y > c0 and y < c1:
                        g[x][y] = 2
            gaps = [y for y in range(c0, c1+1) if g[r0][y] == 0]
            if gaps:
                y = gaps[0]
                g[r0][y] = 2
                # The opening's offset determines which way its beam travels.
                direction = -1 if y-c0 >= (c1-c0)/2 else 1
                x = r0-1
                while 0 <= x < R:
                    yy = y
                    while 0 <= yy < C:
                        g[x][yy] = 2
                        yy += direction
                    break
    return g
